<?php
namespace App\Http\Controllers;
use App\Models\{Appointment,AppointmentConfirmation,Company,User};
use App\Services\{AppointmentReminder,Availability};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class ReminderController extends Controller {
 private function scoped(Request $r){return Appointment::where('company_id',$r->user()->company_id)->when($r->user()->isProfessional(),fn($q)=>$q->where('professional_id',$r->user()->id));}
 private function lock(Request $r):void {Company::whereKey($r->user()->company_id)->lockForUpdate()->firstOrFail();$u=User::whereKey($r->user()->id)->lockForUpdate()->firstOrFail();abort_unless($u->active&&$u->company_id===$r->user()->company_id&&$u->role===$r->user()->role,403);}
 private function response(string $name,array $data){return response()->view('reminders.'.$name,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 public function index(Request $r){$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d','status'=>'nullable|in:scheduled,confirmed,cancelled']);$now=app(Availability::class)->localNow($r->user()->company);$from=$r->input('from')?:$now->toDateString();$to=$r->input('to')?:$now->copy()->addDays(7)->toDateString();if($to<$from)throw \Illuminate\Validation\ValidationException::withMessages(['to'=>'O fim do período deve ser igual ou posterior ao início.']);$appointments=$this->scoped($r)->with(['professional','company','latestConfirmation'])->whereDate('starts_at','>=',$from)->whereDate('starts_at','<=',$to)->whereIn('status',['scheduled','confirmed','cancelled'])->when($r->filled('status'),fn($q)=>$q->where('status',$r->input('status')))->orderBy('starts_at')->orderBy('id')->paginate(20)->withQueryString();return $this->response('index',compact('appointments','from','to'));}
 public function show(Request $r,int $id){$company=(int)$r->user()->company_id;$appointment=$this->scoped($r)->with(['company','professional'=>fn($q)=>$q->where('company_id',$company),'latestConfirmation'=>fn($q)=>$q->where('company_id',$company)])->findOrFail($id);$service=app(AppointmentReminder::class);$link=$appointment->latestConfirmation;$valid=$link&&$service->valid($link,$appointment)&&$service->eligible($appointment);$phone=$service->phone($appointment->client_phone);$message=$valid?$service->message($appointment,$link):null;$history=AppointmentConfirmation::where('company_id',$appointment->company_id)->where('appointment_id',$id)->with(['creator','sender'])->latest('id')->paginate(10);return $this->response('show',compact('appointment','service','link','valid','phone','message','history'));}
 public function issue(Request $r,int $id){$r->validate(['request_id'=>'required|uuid','acknowledge'=>'accepted','renew'=>'nullable|boolean']);$this->scoped($r)->findOrFail($id);DB::transaction(function()use($r,$id){$this->lock($r);$company=(int)$r->user()->company_id;$a=$this->scoped($r)->with(['company','professional'=>fn($q)=>$q->where('company_id',$company)])->lockForUpdate()->findOrFail($id);$service=app(AppointmentReminder::class);abort_unless($service->eligible($a),422,'Somente agendamentos futuros e ativos podem receber links.');$key=hash('sha256','reminder|'.$r->user()->company_id.'|'.$r->user()->id.'|'.$r->input('request_id'));if($old=AppointmentConfirmation::where('request_key',$key)->first()){abort_unless($old->appointment_id===$id,409);return;}$current=$a->latestConfirmation;if(!$r->boolean('renew')&&$current&&$service->valid($current,$a))return;$service->invalidate($a);$token=bin2hex(random_bytes(32));AppointmentConfirmation::create(['company_id'=>$a->company_id,'appointment_id'=>$id,'created_by'=>$r->user()->id,'token'=>$token,'token_hash'=>hash('sha256',$token),'snapshot'=>$service->snapshot($a),'request_key'=>$key,'expires_at'=>$service->deadline($a)]);},3);return redirect()->route('reminders.show',$id)->with('success','Link disponível. Confira o destinatário antes de enviar.');}
 public function sent(Request $r,int $id){$r->validate(['link_id'=>'required|integer','acknowledge'=>'accepted']);DB::transaction(function()use($r,$id){$this->lock($r);$a=$this->scoped($r)->with(['company','professional'])->findOrFail($id);$link=AppointmentConfirmation::where('company_id',$a->company_id)->where('appointment_id',$id)->findOrFail($r->integer('link_id'));$s=app(AppointmentReminder::class);abort_unless($s->eligible($a)&&$s->valid($link,$a),422,'O link foi alterado ou expirou. Reabra a página.');$link->update(['sent_at'=>now(),'sent_by'=>$r->user()->id]);},3);return back()->with('success','Envio informado pela equipe. Isso não confirma entrega nem leitura no WhatsApp.');}
 public function revoke(Request $r,int $id){$r->validate(['link_id'=>'required|integer']);DB::transaction(function()use($r,$id){$this->lock($r);$a=$this->scoped($r)->findOrFail($id);$link=AppointmentConfirmation::where('company_id',$a->company_id)->where('appointment_id',$id)->findOrFail($r->integer('link_id'));if(!$link->revoked_at)$link->update(['revoked_at'=>now()]);},3);return back()->with('success','Link desativado. A situação do agendamento foi preservada.');}
}
